"use client";

import React, { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import "./Home.css"
import Banner from "@/app/components/ui/Banner";
import FeaturedPlaylists from "@/app/components/FeaturedPlaylists/FeaturedPlaylists";
import type { Playlist, DetailViewData } from "@/app/types/music";

import DetailView from "@/app/features/playlist/components/DetailView";

export default function ExplorePage() {
  const [selected, setSelected] = useState<DetailViewData | null>(null);

  /* DETAIL VIEW */
  if (selected) {
    return <DetailView data={selected} onBack={() => setSelected(null)} />;
  }

  /* LIST VIEW */
  return (
    <div id="home" className="home-menu">
      {/* <Banner /> */}

      <h1 className="main-title">Discovery</h1>     

      <FeaturedPlaylists onSelect={setSelected} />
    </div>
  );
}

"use client";

import { useState } from "react";
import { usePlaylists } from "@/app/features/playlist/hooks/usePlaylists";
import { usePlaylistDetail } from "@/app/features/playlist/hooks/usePlaylistDetail";
import { removeSongFromPlaylistService, deletePlaylistService } from "@/app/features/playlist/service";
import DetailView from "@/app/features/playlist/components/DetailView";
import PlaylistCover from "@/app/components/FeaturedPlaylists/PlaylistCover";
import CreatePlaylistModal from "@/app/features/playlist/components/CreatePlaylistModal";
import type { DetailViewData } from "@/app/types/music";
import "./Playlist.css";

export default function PlaylistsPage() {
  const { playlists, loading: playlistsLoading, error, fetchPlaylists } = usePlaylists();
  const [selectedPlaylistId, setSelectedPlaylistId] = useState<number | null>(null);
  const [showCreateModal, setShowCreateModal] = useState(false);

  const { playlist: playlistDetail, loading: detailLoading, fetchPlaylistDetail } = usePlaylistDetail(selectedPlaylistId);

  const handleRemoveSong = async (songId: number) => {
    if (!selectedPlaylistId) return;

    const isConfirm = window.confirm("Bạn có chắc chắn muốn xóa bài hát này khỏi playlist không?");
    if (!isConfirm) return;

    try {
      await removeSongFromPlaylistService(selectedPlaylistId, songId);
      fetchPlaylistDetail();
      fetchPlaylists();
    } catch (err: any) {
      alert("Lỗi khi xóa bài hát: " + err.message);
    }
  };

  const handleDeletePlaylist = async () => {
    if (!selectedPlaylistId) return;

    const isConfirm = window.confirm("Bạn có chắc chắn muốn xóa toàn bộ playlist này không? Hành động này không thể hoàn tác.");
    if (!isConfirm) return;

    try {
      await deletePlaylistService(selectedPlaylistId);
      setSelectedPlaylistId(null);
      fetchPlaylists();
    } catch (err: any) {
      alert("Lỗi khi xóa playlist: " + err.message);
    }
  };

  if (selectedPlaylistId) {
    if (detailLoading) return <div>Đang tải chi tiết playlist...</div>;
    if (!playlistDetail) return <div>Không tìm thấy chi tiết playlist. <button onClick={() => setSelectedPlaylistId(null)}>Quay lại</button></div>;

    const detailData: DetailViewData = {
      type: "playlist",
      title: playlistDetail.name,
      coverImages: playlistDetail.songs?.map((s: any) => s.imageUrl).filter(Boolean) || [],
      tracks: (playlistDetail.songs || []).map((song: any) => ({
        trackId: song.songId || song.id,
        title: song.title,
        duration: song.duration || 0,
        imageUrl: song.imageUrl || "/images/default-song.jpg",
        audioUrl: song.audioUrl,
        artistName: song.artistName || "Unknown",
        genre: "",
        viewCount: 0,
        isVisible: true
      }))
    };

    return <DetailView data={detailData} onBack={() => setSelectedPlaylistId(null)} onRemoveSong={handleRemoveSong} onDeletePlaylist={handleDeletePlaylist} />;
  }

  return (
    <div className="playlist-page">
      <div className="playlist-page-header" style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
        <h1 className="main-title"> Danh sách Playlist</h1>
        <button 
          className="create-btn"
          onClick={() => setShowCreateModal(true)} 
        >
          <i className="fa-solid fa-plus"></i> Tạo playlist mới
        </button>
      </div>

      {showCreateModal && (
        <CreatePlaylistModal 
          onClose={() => setShowCreateModal(false)} 
          onCreated={() => {
            fetchPlaylists();
            setShowCreateModal(false);
          }} 
        />
      )}

      {playlistsLoading ? (
        <div>Đang tải playlists...</div>
      ) : playlists.length === 0 ? (
        <div>Chưa có playlist nào. Hãy tạo một playlist mới.</div>
      ) : (
        <div className="playlist-grid">
          {playlists.map((playlist: any) => (
            <div key={playlist.playlistId} className="playlist-card">
              <div 
                className="playlist-card-cover"
                onClick={() => setSelectedPlaylistId(playlist.playlistId)}
                style={{ cursor: "pointer" }}
              >
                <PlaylistCover 
                  images={playlist.songs?.map((s: any) => s.imageUrl).filter(Boolean) || []} 
                  size={"100%" as any} 
                />
                <button
                  className="playlist-play-btn"
                  onClick={(e) => {
                    // e.stopPropagation();
                    setSelectedPlaylistId(playlist.playlistId)
                  }}
                >
                  <i className="fa-solid fa-play" />
                </button>
              </div>
              <div className="playlist-card-info">
                <h2>{playlist.name}</h2>
                {playlist.description && <p>{playlist.description}</p>}
                <span>{playlist.songs?.length ?? 0} bài hát</span>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useRef, useEffect } from "react";
import Profile from "@/app/features/user/components/Profile";
import styles from "./ProfilePage.module.css";
import { useUser } from "@/app/features/user/context/UserContext";
import { useProfile } from "@/app/features/user/hooks/useProfile";

export default function ProfilePage() {
  const { user } = useUser();
  const { uploadAvatar, isUploading } = useProfile();

  // State lưu URL ảnh preview tạm thời
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);

  // Ref để kết nối với thẻ input file bị ẩn
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Dọn dẹp URL Object khi component unmount để tránh rò rỉ bộ nhớ
  useEffect(() => {
    return () => {
      if (previewUrl) {
        URL.revokeObjectURL(previewUrl);
      }
    };
  }, [previewUrl]);

  // Kích hoạt input file ẩn khi bấm vào nút máy ảnh
  const handleEditClick = () => {
    fileInputRef.current?.click();
  };

  // Xử lý khi người dùng chọn file xong
  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      // 1. Tạo URL tạm để hiển thị preview ngay lập tức
      const objectUrl = URL.createObjectURL(file);
      setPreviewUrl(objectUrl);

      // 2. Sử dụng hook để upload
      try {
        await uploadAvatar(file);
        // Thành công: Xóa preview khi đã có ảnh thật từ DB (hook đã gọi refreshUser)
        setPreviewUrl(null);
      } catch (error) {
        // Thất bại: Trả lại trạng thái cũ
        setPreviewUrl(null);
      }
    }
  };

  // Logic hiển thị Avatar: Ưu tiên ảnh Preview -> Ảnh User từ DB -> Ảnh mặc định
  // Lưu ý: Sửa lại user?.avatar theo đúng key trong database của bạn nhé
  const displayAvatar =
    previewUrl || user?.avatar || "/images/Avatar/avt01.png";

  return (
    <div className={styles.pageContainer}>
      <div className={styles.heroSection}>
        <div className={styles.coverPhoto}></div>

        <div className={styles.userInfo}>
          <div className={styles.avatarWrapper}>
            <img
              src={displayAvatar}
              alt="User Avatar"
              className={styles.largeAvatar}
            />

            <input
              type="file"
              ref={fileInputRef}
              onChange={handleFileChange}
              accept="image/*"
              style={{ display: "none" }}
            />

            <button
              className={styles.editAvatarBtn}
              onClick={handleEditClick}
              title="Thay đổi ảnh đại diện"
              type="button"
            >
              {/* Icon Camera SVG */}
              <svg
                width="20"
                height="20"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
              >
                <path d="M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z"></path>
                <circle cx="12" cy="13" r="4"></circle>
              </svg>
            </button>
          </div>

          <h2 className={styles.displayName}>
            {user?.username || "Người dùng"}
          </h2>
          <span className={styles.premiumBadge}>
            <svg viewBox="0 0 576 512" height="1em">
              <path
                className={styles.logoIcon}
                d="M309 106c11.4-7 19-19.7 19-34c0-22.1-17.9-40-40-40s-40 17.9-40 40c0 14.4 7.6 27 19 34L209.7 220.6c-9.1 18.2-32.7 23.4-48.6 10.7L72 160c5-6.7 8-15 8-24c0-22.1-17.9-40-40-40S0 113.9 0 136s17.9 40 40 40c.2 0 .5 0 .7 0L86.4 427.4c5.5 30.4 32 52.6 63 52.6H426.6c30.9 0 57.4-22.1 63-52.6L535.3 176c.2 0 .5 0 .7 0c22.1 0 40-17.9 40-40s-17.9-40-40-40s-40 17.9-40 40c0 9 3 17.3 8 24l-89.1 71.3c-15.9 12.7-39.5 7.5-48.6-10.7L309 106z"
              ></path>
            </svg>
            Premium Member
          </span>
        </div>
      </div>

      <div className={styles.formContainer}>
        <Profile />
      </div>
    </div>
  );
}

"use client";

import "@/app/styles/globals.css";
import Sidebar from "@/app/components/layout/Sidebar/UserPage/Sidebar";
import Header from "@/app/components/layout/Header/UserPage/Header";
import Player from "@/app/features/player/components/Player";
import { useEffect } from "react";
import { useModal } from "@/app/context/ModalContext";
import { useUser } from "@/app/features/user/context/UserContext";

export default function MainLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const { user, loading } = useUser();
  const { openModal } = useModal();

  useEffect(() => {
    if (loading) return;
    if (!user) openModal("signin");
  }, [user, loading]);

  return (
    <>
      <Sidebar />
      <div className="main">
        <Header />
        <div id="content" className="content">
          {children}
        </div>
      </div>
      <Player />
    </>
  );
}

"use client";

import stylesUser from "@/app/styles/AdminPage/ManageUser.module.css";
import styles from "@/app/styles/AdminPage/ManageAdmin.module.css";
import { useModal } from "@/app/context/ModalContext";
import { useAdmins } from "@/app/features/admin/useAdmins";
import { useAdminUser } from "@/app/features/admin/context/AdminUserContext";
import type { User } from "@/app/types/music";

export default function ManageAdmin() {
  const { openModal } = useModal();
  const { admin: actor } = useAdminUser();
  const { admins, isLoading, error, updateAdminStatus, deleteAdmin } =
    useAdmins();

  if (isLoading) return <p>Đang tải...</p>;
  if (error) return <p>Lỗi tải danh sách admin!</p>;
  if (!admins || admins.length === 0) return null;

  return (
    <div id="admins" className={stylesUser.section}>
      <div>
        {actor?.role === "super_admin" && <button
          style={{ width: "fit-content" }}
          className={stylesUser.add}
          onClick={() => openModal("add-new-admin")}
        >
          <i className="fa-solid fa-plus"></i> Add Admin
        </button>}
      </div>

      <div className={stylesUser.table}>
        <div className={stylesUser.tableHead}>
          <div>ID</div>
          <div>Name</div>
          <div>Email</div>
          <div>Role</div>
          <div>Status</div>
          <div>Option</div>
        </div>
        <div className="table_row">
          {admins.map((admin, index) => (
            <div key={admin.userId} className={stylesUser.row}>
              <div>{index + 1}</div>
              <div>{admin.username}</div>
              <div>{admin.email}</div>
              <div>{admin.role}</div>
              <div className={`${styles.status} ${styles.active}`}>actived</div>
              <div className={stylesUser.rowOption}>
                {(actor?.userId === admin.userId || (actor?.role === "super_admin" && admin.role === "admin")) && <button
                  className={stylesUser.edit}
                  onClick={() => openModal("reset-admin-password", admin)}
                >
                  Edit
                </button>}
                {actor?.role === "super_admin" && admin.role === "admin" && <button
                  className={stylesUser.delete}
                  onClick={() => deleteAdmin(admin.userId)}
                >
                  Delete
                </button>}
                {/* {admin.account_status === "pending" ? (
                  <>
                    <button
                      className={stylesUser.edit}
                      onClick={() => updateAdminStatus(admin.userId, "accept")}
                    >
                      Accept
                    </button>
                    <button
                      className={stylesUser.delete}
                      onClick={() => updateAdminStatus(admin.userId, "reject")}
                    >
                      Reject
                    </button>
                  </>
                ) : (
                  <>
                    <button
                      className={stylesUser.edit}
                      onClick={() => openModal("reset-admin-password", admin)}
                    >
                      Edit
                    </button>
                    <button
                      className={stylesUser.delete}
                      onClick={() => deleteAdmin(admin.userId)}
                    >
                      Delete
                    </button> */}
                {/* </> */}
                {/* )} */}
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

"use client";
import { useState, useEffect, Suspense } from "react";
import { useSearchParams } from "next/navigation";

import styles from "@/app/styles/AdminPage/ManageSong.module.css";
import { useModal } from "@/app/context/ModalContext";
import {
  fetchSongsForManage,
  updateSong,
  deleteSong,
  toggleSongVisibility,
  createSong,
} from "@/app/features/song/song.api";
import Pagination from "@/app/components/ui/Pagination";
import { formatDuration, formatDate } from "@/app/utils/dateHelper";

function SongManagement() {
  const searchParams = useSearchParams();
  const currentPage = Number(searchParams.get("page")) || 1;
  const { openModal } = useModal();
  const [songs, setSongs] = useState<any[]>([]);
  const [totalPages, setTotalPages] = useState(1);
  const [loading, setLoading] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const [debouncedSearch, setDebouncedSearch] = useState("");

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedSearch(searchTerm);
    }, 500);
    return () => clearTimeout(handler);
  }, [searchTerm]);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);

      try {
        const res = await fetchSongsForManage({
          page: currentPage,
          limit: 20,
          search: debouncedSearch,
        });

        setSongs(res.data);
        setTotalPages(res.pagination.totalPages);
      } catch (error) {
        console.error("Fetch songs failed:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [currentPage, debouncedSearch]);

  const openAddModal = () => {
    openModal("song-form", {
      song: null,
      onSave: async (formData: FormData) => {
        try {
          const res = await createSong(formData);

          alert(res.message || "Thêm bài hát thành công!");

          setSongs((prev) => [res.data, ...prev]);
        } catch (error: any) {
          alert(error.message || "Thêm bài hát thất bại");
          throw error;
        }
      },
    });
  };

  const openEditModal = (song: any) => {
    openModal("song-form", {
      song,
      onSave: async (updatedData: any) => {
        const res = await updateSong(song.song_id, updatedData);

        setSongs((prev) =>
          prev.map((s) => (s.song_id === song.song_id ? res.data : s)),
        );
      },
    });
  };

  const handleDelete = async (songId: number) => {
    if (!confirm("Bạn có chắc muốn xoá bài hát này?")) return;

    try {
      setLoading(true);

      await deleteSong(songId);

      // Cập nhật lại UI
      setSongs((prev) => prev.filter((s) => s.song_id !== songId));
    } catch (error: any) {
      alert(error.message || "Xóa bài hát thất bại");
    } finally {
      setLoading(false);
    }
  };

  const handleToggleVisibility = async (songId: number) => {
    console.log("Toggling visibility for song ID:", songId);
    try {
      setLoading(true);

      const res = await toggleSongVisibility(songId);

      setSongs((prev) =>
        prev.map((s) =>
          s.song_id === songId ? { ...s, is_visible: res.isVisible } : s,
        ),
      );
    } catch (error: any) {
      alert(error.message || "Không thể thay đổi trạng thái bài hát");
    } finally {
      setLoading(false);
    }
  };
  console.log("songs: ", songs);

  return (
    <div className={styles.container}>
      <h2 className={styles.header}>Song Management</h2>

      <div className={styles.topBar}>
        <button className={styles.addButton} onClick={openAddModal}>
          + Add New Song
        </button>
        <input
          type="text"
          className={styles.searchInput}
          placeholder="Search songs by title..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      <table className={styles.songTable}>
        <colgroup>
          <col style={{ width: "20%" }} />
          <col style={{ width: "12%" }} />
          <col style={{ width: "8%" }} />
          <col style={{ width: "8%" }} />
          <col style={{ width: "10%" }} />
          <col style={{ width: "8%" }} />
          <col style={{ width: "8%" }} />
          <col style={{ width: "12%" }} />
        </colgroup>
        <thead>
          <tr>
            <th>Title</th>
            <th>Artist</th>
            <th>Genre</th>
            <th>View</th>
            <th>updated date</th>
            <th>Duration</th>
            <th>Hide</th>
            <th>Actions</th>
          </tr>
        </thead>

        <tbody>
          {songs.map((song) => (
            <tr key={song.song_id}>
              <td>{song.title}</td>
              <td>
                {song.artists?.map((a: any) => a.name).join(", ") || "Unknown"}
              </td>
              <td>{song.genre}</td>
              <td>{song.view_count}</td>
              <td>{formatDate(song.fetched_at)}</td>
              <td>{formatDuration(song.duration)}</td>
              <td>
                <button
                  className={` ${
                    song.is_visible ? styles.visibilityBtn : styles.hidden
                  }`}
                  onClick={() => handleToggleVisibility(song.song_id)}
                  disabled={loading}
                >
                  {song.is_visible ? "Hidden" : "Visible"}
                </button>
              </td>
              <td>
                <button
                  className={styles.editBtn}
                  onClick={() => openEditModal(song)}
                >
                  Edit
                </button>
                <button
                  className={styles.deleteBtn}
                  onClick={() => handleDelete(song.song_id)}
                >
                  Delete
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      <Pagination currentPage={currentPage} totalPages={totalPages} />
    </div>
  );
}

export default function SongManagementPageWrapper() {
  return (
    <Suspense fallback={<div>Loading...</div>}>
      <SongManagement />
    </Suspense>
  );
}

"use client";

import styles from "@/app/styles/AdminPage/ManageUser.module.css";
import { useUsers } from "@/app/features/user/useUsers";
import { useModal } from "@/app/context/ModalContext";
import type { User } from "@/app/types/music";

export default function ManageUser() {
  const { users, isLoading, error, deleteUser } = useUsers();
  const { openModal } = useModal();

  if (isLoading) return <p>Đang tải...</p>;
  if (error) return <p>Lỗi tải danh sách user!</p>;
  if (!users || users.length === 0) return null;

  return (
    <div id="users" className={styles.section}>
      {/* <div>
        <button style={{ width: "fit-content" }} className={styles.add}>
          <i className="fa-solid fa-plus"></i> Add User
        </button>
      </div> */}

      <div className={styles.table}>
        <div className={styles.tableHead}>
          <div>ID</div>
          <div>Username</div>
          <div>Email</div>
          <div>Role</div>
          <div>Status</div>
          <div>Options</div>
        </div>

        <div className="table_row">
          {users.map((user, index) => (
            <div key={user.userId} className={styles.row}>
              <div>{index + 1}</div>
              <div>{user.username}</div>
              <div>{user.email}</div>
              <div>{user.role}</div>

              <div>
                <span
                  className={
                    user.actStatus === "online"
                      ? `${styles.status} ${styles.active}`
                      : `${styles.status} ${styles.inactive}`
                  }
                >
                  {user.actStatus}
                </span>
              </div>

              <div className={styles.rowOption}>
                <button
                  className={styles.edit}
                  onClick={() => openModal("edit-user-profile", user)}
                >
                  Edit
                </button>

                <button
                  className={styles.delete}
                  onClick={() => deleteUser(user.userId)}
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

"use client";
import { useEffect } from "react";
import styles from "./SongDetailModal.module.css";
import { formatDuration, formatDate } from "@/app/utils/dateHelper";

interface Props {
  song: any;
  onClose: () => void;
  onApprove: (id: number) => void;
  onReject: (id: number) => void;
  loading: boolean;
}

export default function SongDetailModal({
  song,
  onClose,
  onApprove,
  onReject,
  loading,
}: Props) {
  // Đóng modal khi bấm Escape
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    window.addEventListener("keydown", handler);
    return () => window.removeEventListener("keydown", handler);
  }, [onClose]);

  const genres =
    song.genres?.map((g: any) => g.name).join(", ") || "Chưa có";
  const artists =
    song.artists?.map((a: any) => a.name).join(", ") || "Unknown";

  return (
    <div className={styles.overlay} onClick={onClose}>
      <div className={styles.modal} onClick={(e) => e.stopPropagation()}>
        {/* Header */}
        <div className={styles.modalHeader}>
          <h2>Chi tiết bài hát</h2>
          <button className={styles.closeBtn} onClick={onClose}>
            ×
          </button>
        </div>

        {/* Body */}
        <div className={styles.body}>
          {/* Cover + basic info */}
          <div className={styles.topRow}>
            {song.image_url ? (
              <img
                src={song.image_url}
                alt={song.title}
                className={styles.cover}
              />
            ) : (
              <div className={styles.coverPlaceholder}>🎵</div>
            )}

            <div className={styles.basicInfo}>
