"use client";

import React, { useState, useEffect, useRef } from "react";
import styles from "./search.module.css";
import { FaSearch, FaTimes } from "react-icons/fa";
import { searchSongs } from "@/app/features/song/song.api";
import { Track } from "@/app/types/music";

interface SearchBarProps {
  setResults: (results: Track[]) => void;
  setSearchTerm: (searchTerm: string) => void;
  setIsSearchFocused: (focused: boolean) => void;
}

const SearchBar = ({
  setResults,
  setSearchTerm,
  setIsSearchFocused,
}: SearchBarProps) => {
  const [input, setInput] = useState("");
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const handler = setTimeout(async () => {
      const value = input.trim();

      if (!value) {
        setResults([]);
        return;
      }

      try {
        const tracks = await searchSongs(value, 10);

        setResults(tracks || []);
      } catch (err) {
        console.error("Search error:", err);
        const errorMessage =
          err instanceof Error ? err.message : "Lỗi tìm kiếm";
        setResults([]);
      }
    }, 300);

    return () => clearTimeout(handler);
  }, [input]);

  const handleChange = (value: string) => {
    setInput(value);
    setSearchTerm(value);
  };

  const clearInput = () => {
    setInput("");
    setSearchTerm("");
    setResults([]);
    inputRef.current?.focus();
  };

  return (
    <div className={styles.inputWrapper}>
      <FaSearch
        className={`${styles.icon} ${styles.searchIcon}`}
        onClick={() => inputRef.current?.focus()}
      />

      <div className={styles.inputContainer}>
        <input
          className={styles.input}
          ref={inputRef}
          placeholder="Bạn muốn phát nội dung gì?"
          value={input}
          onChange={(e) => handleChange(e.target.value)}
          onFocus={() => setIsSearchFocused(true)}
        />

        {input && (
          <FaTimes
            className={`${styles.icon} ${styles.clearIcon}`}
            onClick={clearInput}
            onMouseDown={(e) => e.preventDefault()}
          />
        )}
      </div>
    </div>
  );
};

export default SearchBar;

"use client";

import React from "react";
import { useState } from "react";
import styles from "./search.module.css";
import { Track } from "@/app/types/music";
import { usePlayer } from "@/app/features/player/context/PlayerContext";

interface SearchResultProps {
  result: Track;
  searchTerm: string;
}

const SearchResult = ({ result, searchTerm }: SearchResultProps) => {
  const { setPlaylist } = usePlayer();

  const highlight = (text: string, term: string) => {
    if (!term) return text;

    const parts = text.split(new RegExp(`(${term})`, "gi"));

    return parts.map((part, i) => {
      const isMatch = part.toLowerCase() === term.toLowerCase();

      return isMatch ? (
        <span key={i} className={styles.highlight}>
          {part}
        </span>
      ) : (
        <React.Fragment key={i}>{part}</React.Fragment>
      );
    });
  };
  return (
    <div
      className={styles.resultItem}
      onMouseDown={() => {
        setPlaylist([{ ...result }], 0, "search");
      }}
    >
      <img
        src={result.imageUrl || "/images/default-song.jpg"}
        className={styles.resultImg}
      />

      <div className={styles.resultInfo}>
        <div className={styles.resultTitle}>
          {highlight(result.title, searchTerm)}
        </div>
        <div className={styles.resultArtist}>{result.artistName}</div>
      </div>
    </div>
  );
};

export default SearchResult;

"use client";
import { createContext, useContext, useState, ReactNode } from "react";
import Modal from "@/app/components/ui/Modal";
import Profile from "@/app/features/user/components/Profile";
import EditUserProfile from "../features/user/components/EditUserProfile";
import ChangePassword from "../features/auth/components/ChangePassword";
import SongFormModal from "../features/admin/components/SongFormModal";
import UploadSongModal from "../features/song/components/UploadSongModal";

import dynamic from "next/dynamic";

// Dynamic import cho user
const SignInPage = dynamic(() => import("@/app/(Pages)/login/page"));
const RegisterPage = dynamic(() => import("@/app/(Pages)/register/page"));

// Dynamic import cho admin
const SignInAdminPage = dynamic(
  () => import("@/app/(Pages)/administrator/login/page"),
);

const AddNewAdmin = dynamic(
  () => import("@/app/features/admin/components/AddAdmin"),
);

const ResetAdminPassword = dynamic(
  () => import("@/app/features/admin/components/ResetAdminPassword"),
);

type ModalType =
  | "profile"
  | "signin"
  | "register"
  | "signin-admin"
  | "register-admin"
  | "add-new-admin"
  | "edit-user-profile"
  | "change-password"
  | "reset-admin-password"
  | "song-form"
  | "upload-song"
  | null;

interface ModalContextType {
  openModal: (type: Exclude<ModalType, null>, data?: any) => void;
  closeModal: () => void;
  modalData: any;
}

const ModalContext = createContext<ModalContextType | undefined>(undefined);

export function ModalProvider({ children }: { children: ReactNode }) {
  const [isOpen, setIsOpen] = useState(false);
  const [modalContent, setModalContent] = useState<ModalType>(null);
  const [modalData, setModalData] = useState<any>(null);

  const openModal = (type: Exclude<ModalType, null>, data?: any) => {
    setModalContent(type);
    setModalData(data || null);
    setIsOpen(true);
  };

  const closeModal = () => {
    setIsOpen(false);
    setModalContent(null);
  };

  const renderModalContent = () => {
    switch (modalContent) {
      case "signin":
        return <SignInPage />;
      case "register":
        return <RegisterPage />;
      case "add-new-admin":
        return <AddNewAdmin />;
      case "edit-user-profile":
        return <EditUserProfile userData={modalData} />;
      case "change-password":
        return <ChangePassword />;
      case "song-form":
        return (
          <SongFormModal song={modalData.song} onSave={modalData.onSave} />
        );
      case "upload-song":
        return <UploadSongModal />;
      case "reset-admin-password":
        return <ResetAdminPassword admin={modalData} />;
      default:
        return null;
    }
  };

  return (
    <ModalContext.Provider value={{ openModal, closeModal, modalData }}>
      {children}
      <Modal isOpen={isOpen} onClose={closeModal}>
        {renderModalContent()}
      </Modal>
    </ModalContext.Provider>
  );
}

export function useModal() {
  const context = useContext(ModalContext);
  if (!context) {
    throw new Error("useModal phải được gọi trong ModalProvider");
  }
  return context;
}

