interface AdminUserContextType {
  admin: User | null;
  setAdmin: React.Dispatch<React.SetStateAction<User | null>>;
  loading: boolean;
  checkAdmin: () => Promise<void>;
}

const AdminUserContext = createContext<AdminUserContextType | undefined>(
  undefined,
);

export const AdminUserProvider = ({
  children,
}: {
  children: React.ReactNode;
}) => {
  const [admin, setAdmin] = useState<User | null>(null);
  const [loading, setLoading] = useState<boolean>(true);

  const checkAdmin = async () => {
    console.log("🚀 checkAdmin START");
    setLoading(true);
    try {
      const data = await getCurrentAdminService();
      console.log("✅ API SUCCESS:", data);
      setAdmin(data.data);
    } catch (err) {
      console.log("❌ API ERROR:", err);
      setAdmin(null);
    } finally {
      console.log("🏁 FINALLY - SET LOADING FALSE");
      setLoading(false);
    }
  };

  useEffect(() => {
    checkAdmin();
  }, []);

  return (
    <AdminUserContext.Provider value={{ admin, setAdmin, loading, checkAdmin }}>
      {children}
    </AdminUserContext.Provider>
  );
};

export const useAdminUser = (): AdminUserContextType => {
  const context = useContext(AdminUserContext);
  if (!context) {
    throw new Error("useAdminUser phải được dùng trong AdminUserProvider");
  }
  return context;
};

"use client";

import { readApiResponse } from "../../lib/api-contract";
import useSWR, { mutate } from "swr";
import { getAdmins, AcceptOrReject } from "@/app/features/auth/authApi";
import { deleteAccount } from "@/app/features/user/accountApi";
import { User } from "../../types/music";

// Fetcher dùng chung
const fetcher = async (): Promise<User[]> => {
  const res = await getAdmins();
  if (!res.ok) throw new Error("Không thể tải danh sách admin");

  const result = await readApiResponse(res);

  return result.data.map((item: any) => ({
    userId: item.user_id,
    username: item.username,
    email: item.email,
    role: item.role,
    activity_status: item.activity_status,
    account_status: item.is_active,
  }));
};

// Hook dùng chung
export function useAdmins() {
  const { data, error, isLoading } = useSWR<User[]>("admins", fetcher);

  // Cập nhật trạng thái admin
  const updateAdminStatus = async (id: number, status: string) => {
    try {
      const res = await AcceptOrReject(id, status);
      const dataRes = await readApiResponse(res);

      alert(dataRes.message);

      if (res.ok) {
        // Optimistic update
        mutate<User[]>(
          "admins",
          (admins) =>
            admins?.map((u) =>
              u.userId === id ? { ...u, activity_status: status } : u,
            ),
          false,
        );

        // Revalidate
        mutate("admins");
      }
    } catch (error) {
      console.error("Lỗi khi cập nhật trạng thái:", error);
      alert("Lỗi hệ thống khi cập nhật trạng thái.");
    }
  };

  // Xóa admin
  const deleteAdmin = async (userId: number) => {
    try {
      const res = await deleteAccount(userId);

      let dataRes;
      try {
        dataRes = await readApiResponse(res);
      } catch {
        dataRes = { message: "Không thể đọc phản hồi từ máy chủ." };
      }

      alert(dataRes.message || "Không có phản hồi từ server.");

      if (res.ok) {
        mutate<User[]>(
          "admins",
          (admins) => admins?.filter((u) => u.userId !== userId),
          false,
        );
        mutate("admins");
      }
    } catch (error) {
      console.error("Lỗi khi xóa:", error);
      alert("Không thể kết nối đến máy chủ.");
    }
  };

  return {
    admins: data ?? [],
    isLoading,
    error,
    updateAdminStatus,
    deleteAdmin,
    refreshAdmins: () => mutate("admins"),
  };
}

import { fetchArtistsApi, fetchArtistDetailApi, fetchTopArtistsApi } from "./artist.api";
import type { DetailViewData } from "@/app/types/music";
import type {Artist} from "./types/artist.types"

export const artistService = {
  getArtists: async (): Promise<Artist[]> => {
    const json = await fetchArtistsApi();
    
    return json.data.map((a: any) => ({
      artistId: a.artist_id,
      name: a.name,
      imageUrl: a.image_url ?? "/images/default-artist.png",
    }));
  },

  getTopArtists: async (limit: number = 20): Promise<Artist[]> => {
    const json = await fetchTopArtistsApi(limit);
    
    return json.data.map((a: any) => ({
      artistId: a.artist_id,
      name: a.name,
      imageUrl: a.image_url ?? "/images/default-artist.png",
      totalListens: a.total_listens, // dùng sau này
    }));
  },

  getArtistDetail: async (artistId: number): Promise<DetailViewData> => {
    const json = await fetchArtistDetailApi(artistId);
    const artist = json.data;

    const songs = artist.songs ?? [];

    const artistImage =
      artist.image_url ?? songs[0]?.image_url ?? "/images/default-artist.png";

    return {
      type: "artist",
      title: artist.name,
      coverImages: [artistImage],
      tracks: songs.map((s: any) => ({
        trackId: s.song_id,
        title: s.title,
        duration: s.duration,
        imageUrl: s.image_url,
        audioUrl: s.audio_url,
        artistName: artist.name,
      })),
    };
  },
};

