import { readApiResponse } from "../../../lib/api-contract";
import { useState } from "react";
import styles from "@/app/styles/form.module.css";
import { useModal } from "@/app/context/ModalContext";
import { changePassword } from "../../user/accountApi";
import { validatePassword } from "@/app/utils/passwordValidator";

export default function ChangePassword() {
  const [oldPassword, setOldPassword] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [confirmPW, setConfirmPW] = useState("");
  const { openModal } = useModal();

  const handleChangePassword = async (e: React.FormEvent) => {
    e.preventDefault();

    if (newPassword !== confirmPW) {
      alert("Mật khẩu xác nhận không khớp");
      return;
    }

    const passwordError = validatePassword(confirmPW);
    if (passwordError) {
      alert(passwordError);
      return;
    }

    try {
      const res = await changePassword(oldPassword, confirmPW);
      const data = await readApiResponse(res);
      alert(data.message);
    } catch (error) {
      console.error("Lỗi khi gọi api changPassword.");
    }
  };

  return (
    <div className={styles.formContainer}>
      <h1 className={styles.title}>Change your password</h1>

      <form onSubmit={handleChangePassword}>
        <input
          type="password"
          placeholder="Old Password"
          className={styles.input}
          value={oldPassword}
          onChange={(e) => setOldPassword(e.target.value)}
        />

        <input
          type="password"
          placeholder="New Password"
          className={styles.input}
          value={newPassword}
          onChange={(e) => setNewPassword(e.target.value)}
        />

        <input
          type="password"
          placeholder="Password Confirmation"
          className={styles.input}
          value={confirmPW}
          onChange={(e) => setConfirmPW(e.target.value)}
        />

        <button className={styles.button}>Change</button>
      </form>
    </div>
  );
}

"use client";
import { createContext, useContext, useState, useCallback } from "react";
import { toggleLikeSong, getLikeStatus } from "../like.api";
// import { fetchLikedSongs } from "@/app/utils/songApi";
import { getMyFavoriteSongs } from "../favorite.api";
import { mapSongToTrack } from "@/app/utils/song.mapper";

import type { Track } from "@/app/types/music";

const LikeContext = createContext<any>(null);

export const LikeProvider = ({ children }: any) => {
  const [likedMap, setLikedMap] = useState<Record<number, boolean>>({});
  const [likedSongsList, setLikedSongsList] = useState<Track[]>([]);

  const fetchLikeStatus = async (songId: number) => {
    if (likedMap[songId] !== undefined) return;

    const res = await getLikeStatus(songId);

    setLikedMap((prev) => ({
      ...prev,
      [songId]: res.liked,
    }));
  };

  const toggleLike = async (songId: number) => {
    const prevLiked = likedMap[songId];

    setLikedMap((prev) => ({
      ...prev,
      [songId]: !prevLiked,
    }));

    try {
      await toggleLikeSong(songId);

      if (prevLiked) {
        // unlike → remove khỏi list
        setLikedSongsList((prev) =>
          prev.filter((song) => song.trackId !== songId),
        );
      } else {
        // like → fetch lại list
        fetchLikedSongsList();
      }
    } catch (err) {
      // rollback nếu fail
      setLikedMap((prev) => ({
        ...prev,
        [songId]: prevLiked,
      }));
    }
  };

  // Lấy danh sách bài hát đã like
  const fetchLikedSongsList = useCallback(async () => {
    try {
      const res = await getMyFavoriteSongs(1, 20);

      // map từ backend raw → Track
      const songs: Track[] = res.data.map((fav: any) =>
        mapSongToTrack(fav.song),
      );

      setLikedSongsList(songs);

      // sync lại map
      const newMap: Record<number, boolean> = {};
      songs.forEach((song) => {
        newMap[song.trackId] = true;
      });

      setLikedMap(newMap);
    } catch (err) {
      console.error("fetchLikedSongsList error:", err);
    }
  }, []);

  return (
    <LikeContext.Provider
      value={{
        likedMap,
        likedSongsList,
        fetchLikeStatus,
        fetchLikedSongsList,
        toggleLike,
      }}
    >
      {children}
    </LikeContext.Provider>
  );
};

export const useLikeContext = () => useContext(LikeContext);

import { readApiResponse } from "../../lib/api-contract";
import type { Playlist, Track, DetailViewData } from "@/app/types/music";

const API_URL =
  "/api";

export async function fetchDailyMixes(): Promise<Playlist[]> {
  const res = await fetch(`${API_URL}/playlists/daily-mixes`, {
    cache: "no-store",
    next: { revalidate: 0 },
  });
  const json = await readApiResponse(res);

  return json.data.map((pl: any) => ({
    playlistId: pl.playlist_id,
    name: pl.name,
    coverImages: pl.tracks.map((t: any) => t.image_url).slice(0, 4),
    tracks: [],
  }));
}

export async function fetchDailyMixDetail(
  playlistId: number,
): Promise<DetailViewData> {
  const res = await fetch(`${API_URL}/playlists/daily-mix/${playlistId}`, {
    cache: "no-store",
    next: { revalidate: 0 },
  });
  const json = await readApiResponse(res);
  const pl = json.data;

  return {
    type: "playlist",
    title: pl.name,
    coverImages: pl.Songs.map((s: any) => s.image_url).slice(0, 4),
    tracks: pl.Songs.map((s: any) => ({
      trackId: s.song_id,
      title: s.title,
      duration: s.duration,
      imageUrl: s.image_url,
      audioUrl: s.audio_url,
      artistName: s.artist_name,
      albumName: s.album_name,
    })),
  };
}

"use client";

import React, { useEffect, useState, Suspense } from "react";
import Link from "next/link";
import { useRouter, usePathname, useSearchParams } from "next/navigation";
import "@/app/features/player/components/Player.css";
import { usePlayer } from "@/app/features/player/context/PlayerContext";
import { useLikeContext } from "@/app/features/like/context/LikeContext";
import PopUp from "../../../components/ui/PopUp";
import AddToPlaylistModal from "@/app/features/playlist/components/AddToPlaylistModal";
import { IoHeart, IoHeartOutline } from "react-icons/io5";

const PlayerContent: React.FC = () => {
  const {
    currentTrack,
    isPlaying,
    next,
    prev,
    togglePlay,
    audioState,
    seek,
    setVolume,
    isShuffle,
    toggleShuffle,
    isRepeat,
    toggleRepeat,
  } = usePlayer();
  const { likedMap, toggleLike, fetchLikeStatus } = useLikeContext();

  const [volumeUI, setVolumeUI] = useState(50);
  const [isMuted, setIsMuted] = useState(false);
  const [showUserMenu, setShowUserMenu] = useState(false);
  const [showAddToPlaylist, setShowAddToPlaylist] = useState(false);
  // state khóa nút like chống spam click
  const [isLiking, setIsLiking] = useState(false);

  const router = useRouter();
  const pathname = usePathname();
  const searchParams = useSearchParams();

  // ── Sync track id into URL ──
  useEffect(() => {
    if (!currentTrack?.trackId) return;
    if (searchParams.get("track") === String(currentTrack.trackId)) return;

    const params = new URLSearchParams(searchParams.toString());
    params.set("track", String(currentTrack.trackId));
    router.replace(`${pathname}?${params.toString()}`, { scroll: false });
  }, [currentTrack?.trackId, pathname, router, searchParams]);

  // ── Like status ──
  useEffect(() => {
    if (currentTrack?.trackId) fetchLikeStatus(currentTrack.trackId);
  }, [currentTrack?.trackId, fetchLikeStatus]);

  const liked = currentTrack
    ? (likedMap[currentTrack.trackId] ?? false)
    : false;

  // ── Progress bar ──
  const { currentTime, duration } = audioState;
  const progress = duration ? (currentTime / duration) * 100 : 0;

  const handleSeek = (e: React.ChangeEvent<HTMLInputElement>) => {
    const prog = Number(e.target.value);
    if (!duration) return;
    const newTime = (prog / 100) * duration;
    seek(newTime);
  };

  // ── Volume ──
  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newVolume = Number(e.target.value);
    setVolumeUI(newVolume);
    setVolume(newVolume / 100);
    setIsMuted(newVolume === 0);
  };

  const toggleMute = () => {
    if (isMuted) {
      const vol = volumeUI / 100 || 0.5;
      setVolume(vol);
      setIsMuted(false);
    } else {
      setVolume(0);
      setIsMuted(true);
    }
  };

  // ── Helpers ──
  const formatTime = (time: number) => {
    if (!time || isNaN(time)) return "0:00";
    const minutes = Math.floor(time / 60);
    const seconds = Math.floor(time % 60);
    return `${minutes}:${seconds.toString().padStart(2, "0")}`;
  };

  const getVolumeIcon = () => {
    if (isMuted || volumeUI === 0) return "fa-volume-xmark";
    if (volumeUI < 50) return "fa-volume-low";
    return "fa-volume-high";
  };

  // HÀM XỬ LÝ TRÁNH SPAM CLICK
  const handleLikeClick = async () => {
    if (!currentTrack || isLiking) return; // Đang xử lý thì bỏ qua

    setIsLiking(true); // Khóa nút
    try {
      await toggleLike(currentTrack.trackId);
    } catch (error) {
      console.error("Lỗi khi like:", error);
    } finally {
      // Mở khóa nút sau 500ms (Debounce nhẹ)
      setTimeout(() => {
        setIsLiking(false);
      }, 500);
    }
  };

  return (
    <footer className="bottom-bar-player">
      
      {/* ── TRÁI: Playback controls ── */}
      <div className="player-left">
        <button
          className="play"
          onClick={toggleShuffle}
          style={{ color: isShuffle ? "var(--tt-orange)" : "var(--tt-text-muted)" }}
        >
          <i className="fa-solid fa-shuffle" />
        </button>
        <button id="prevBtn" className="play" onClick={() => prev()}>
          <i className="fa-solid fa-backward-step" />
        </button>
        <button id="playBtn" className="play-btn" onClick={togglePlay}>
          <i className={isPlaying ? "fas fa-pause" : "fas fa-play"} />
        </button>
        <button id="nextBtn" className="play" onClick={() => next()}>
          <i className="fa-solid fa-forward-step" />
        </button>
        <button
          className="play"
          onClick={toggleRepeat}
          style={{ color: isRepeat ? "var(--tt-orange)" : "var(--tt-text-muted)" }}
        >
          <i className="fa-solid fa-repeat" />
        </button>
      </div>

      {/* ── GIỮA: Track info & Progress ── */}
      <div className="player-center">
        <div className="center-wrapper">
          {/* Hàng trên: Ảnh bìa + Text */}
          <div className="center-info">
            <Link
              className="center-cover"
              scroll={false}
              href={`/DetailSong?track=${currentTrack?.trackId ?? ""}`}
            >
              <img
                src={currentTrack?.imageUrl || "/images/default-song.jpg"}
                alt="cover"
              />
            </Link>
            <div className="center-text">
              <span className="song-tittle">{currentTrack?.title || "—"}</span>
              <span className="artist-name">{currentTrack?.artistName || "—"}</span>
            </div>
          </div>

          {/* Hàng dưới: Thanh tiến trình + Thời gian */}
          <div className="run">
            <span className="current-time">{formatTime(currentTime)}</span>
            <input
              type="range"
              className="seek-bar"
              value={progress || 0}
              min={0}
              max={100}
              onChange={handleSeek}
              style={{
                // Tô màu phần đã phát bằng linear-gradient
                background: `linear-gradient(to right, var(--tt-text-primary, #111) ${progress || 0}%, rgba(0,0,0,0.1) ${progress || 0}%)`
              }}
            />
            <span className="music-time">{formatTime(duration)}</span>
          </div>
        </div>
      </div>

      {/* ── PHẢI: Actions & Volume ── */}
      <div className="player-right">
        <div className="song-actions">
          <button
            className={`icon-btn like-icon ${liked ? "liked" : ""}`}
            onClick={handleLikeClick}
            disabled={!currentTrack || isLiking}
            style={{
              opacity: isLiking ? 0.5 : 1,
              cursor: isLiking ? "wait" : "pointer",
            }}
          >
            {liked ? (
              <IoHeart className="fa-solid fa-heart" />
            ) : (
              <IoHeartOutline className="fa-regular fa-heart" />
            )}
          </button>
          
          <div className="menu-wrapper" style={{ position: "relative" }}>
            <button
              className="icon-btn expand-icon"
              onClick={() => setShowUserMenu((v) => !v)}
            >
              <i className="fa-solid fa-ellipsis" />
            </button>

            {showUserMenu && (
              <PopUp show={showUserMenu} onClose={() => setShowUserMenu(false)}>
                <div className="Other-options-popup">
                  <button>
                    <i className="fa-regular fa-heart" />
                    <span>Thêm vào yêu thích</span>
                  </button>
                  <button
                    onClick={() => {
                      setShowAddToPlaylist(true);
                      setShowUserMenu(false);
                    }}
                  >
                    <i className="fa-solid fa-circle-plus" />
                    <span>Thêm vào playlist</span>
                  </button>
                  <button>
                    <i className="fa-regular fa-flag" />
                    <span>Báo cáo</span>
                  </button>
                </div>
              </PopUp>
            )}
          </div>
        </div>

        <div className="vol">
          <button className="volume" onClick={toggleMute}>
            <i className={`fa-solid ${getVolumeIcon()}`} />
          </button>
          <input
            className="seek-volume"
            type="range"
            value={isMuted ? 0 : volumeUI}
            min={0}
            max={100}
            onChange={handleVolumeChange}
            style={{
              // Tô màu phần âm lượng hiện tại
              background: `linear-gradient(to right, var(--tt-text-primary, #111) ${isMuted ? 0 : volumeUI}%, rgba(0,0,0,0.1) ${isMuted ? 0 : volumeUI}%)`
            }}
          />
        </div>
      </div>

      {/* ── Add to Playlist Modal ── */}
