"use client";

import { useState } from "react";
import { createPlaylistService } from "../service";
import "@/app/features/playlist/components/CreatePlaylistModal.css";

type Props = {
  onClose: () => void;
  onCreated?: () => void;
  isNested?: boolean;
};

export default function CreatePlaylistModal({
  onClose,
  onCreated,
  isNested = false,
}: Props) {
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const handleSubmit = async () => {
    if (!name.trim()) {
      setError("Vui lòng nhập tên playlist");
      return;
    }

    try {
      setLoading(true);
      setError("");

      await createPlaylistService(name, description);

      onCreated?.();
      onClose();
    } catch (err: any) {
      setError(
        err.message || "Lỗi khi tạo playlist. Vui lòng thử lại.",
      );
    } finally {
      setLoading(false);
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === "Enter" && (e.ctrlKey || e.metaKey)) {
      handleSubmit();
    }
  };

  if (isNested) {
    // Nested modal style for use inside AddToPlaylistModal
    return (
      <div className="create-playlist-nested-overlay" onClick={onClose}>
        <div
          className="create-playlist-nested-content"
          onClick={(e) => e.stopPropagation()}
        >
          <div className="nested-header">
            <h3>Tạo Playlist Mới</h3>
            <button className="nested-close-btn" onClick={onClose}>
              ✕
            </button>
          </div>

          {error && <div className="error-message">{error}</div>}

          <div className="nested-form">
            <input
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="Tên playlist"
              className="input-field"
              disabled={loading}
              autoFocus
            />

            <textarea
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              onKeyPress={handleKeyPress}
              placeholder="Mô tả (tùy chọn)"
              className="textarea-field"
              disabled={loading}
              rows={3}
            />
          </div>

          <div className="nested-actions">
            <button className="cancel-btn" onClick={onClose} disabled={loading}>
              Hủy
            </button>
            <button
              className="submit-btn"
              onClick={handleSubmit}
              disabled={loading}
            >
              {loading ? "Đang tạo..." : "Tạo Playlist"}
            </button>
          </div>
        </div>
      </div>
    );
  }

  // Standard modal style
  return (
    <div className="create-playlist-overlay" onClick={onClose}>
      <div
        className="create-playlist-content"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="header">
          <h2>Tạo Playlist Mới</h2>
          <button className="close-btn" onClick={onClose}>
            ✕
          </button>
        </div>

        {error && <div className="error-message">{error}</div>}

        <div className="form">
          <input
            type="text"
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder="Tên playlist"
            className="input-field"
            disabled={loading}
            autoFocus
          />

          <textarea
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            onKeyPress={handleKeyPress}
            placeholder="Mô tả (tùy chọn)"
            className="textarea-field"
            disabled={loading}
            rows={3}
          />
        </div>

        <div className="actions">
          <button className="cancel-btn" onClick={onClose} disabled={loading}>
            Hủy
          </button>
          <button
            className="submit-btn"
            onClick={handleSubmit}
            disabled={loading}
          >
            {loading ? "Đang tạo..." : "Tạo Playlist"}
          </button>
        </div>
      </div>
    </div>
  );
}

"use client";

import React, { useEffect, useRef } from "react";
import type { DetailViewData } from "@/app/types/music";
import { usePlayer } from "@/app/features/player/context/PlayerContext";
import PlaylistCover from "@/app/components/FeaturedPlaylists/PlaylistCover";
import { formatDuration } from "@/app/utils/dateHelper";
import styles from "./DetailView.module.css";
import { MdArrowBackIosNew } from "react-icons/md";
import { IoShareOutline, IoTrashOutline } from "react-icons/io5";
import { IoHeart } from "react-icons/io5";
import { FaPlay } from "react-icons/fa";
import { FaPause } from "react-icons/fa";

interface Props {
  data: DetailViewData;
  onBack: () => void;
  onRemoveSong?: (songId: number) => void;
  onDeletePlaylist?: () => void;
}

const DetailView: React.FC<Props> = ({ data, onBack, onRemoveSong, onDeletePlaylist }) => {
  const { currentTrack, setPlaylist, isPlaying, togglePlay } = usePlayer();
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // Khi component mount, lập tức cuộn container về đầu trang
    containerRef.current?.scrollIntoView({ behavior: "auto", block: "start" });
  }, []);

  const isCurrentPlaylistActive = currentTrack && data.tracks.some(t => t.trackId === currentTrack.trackId);

  const tracks = data.tracks;
  const title = data.title;
  const cover = data.coverImages;

  const handlePlaySong = (index: number) => {
    if (tracks.length === 0) return;

    setPlaylist(tracks, index);
  };

  return (
    <div ref={containerRef} className={styles.playlistDetail}>
      {/* BACKGROUND */}
      <div className={styles.playlistBg}>
        <PlaylistCover images={cover ?? []} size={800} />
        <div className={styles.playlistBgOverlay} />
      </div>

      <button onClick={onBack} className={styles.backButton}>
        <MdArrowBackIosNew />
      </button>

      <div className={styles.playlistHeader}>
        <div className={styles.playlistInfo}>
          <PlaylistCover images={cover ?? []} size={200} />

          <div className={styles.playlistContent}>
            <div className={styles.playlistType}>
              {data.type === "playlist"
                ? `Playlist · ${tracks.length} bài hát`
                : `Artist · ${tracks.length} bài hát`}
            </div>

            <h1 className={styles.playlistTitle}>{title}</h1>

            <div className={styles.playlistActions}>
              <div className={styles.playlistIcons}>
                <IoHeart className={styles.icon} />
                <span className={styles.count}>999K</span>
                <IoShareOutline className={styles.icon}/>
                <span className={styles.count}>0</span>
                {onDeletePlaylist && data.type === "playlist" && (
                  <button
                    onClick={onDeletePlaylist}
                    title="Xóa playlist"
                    style={{
                      background: "transparent",
                      border: "none",
                      display: "flex",
                      alignItems: "center",
                      cursor: "pointer",
                      marginLeft: "10px"
                    }}
                  >
                    <IoTrashOutline className={styles.icon} style={{ color: "#ff4b4b" }} />
                  </button>
                )}
                <span className={`${styles.icon} ${styles.more}`}>⋯</span>
              </div>

              <button
                className={styles.playPlaylists}
                onClick={() => {
                  if (tracks.length === 0) return;
                  if (isCurrentPlaylistActive) {
                    togglePlay();
                  } else {
                    setPlaylist(tracks, 0);
                  }
                }}
              >
                {isCurrentPlaylistActive && isPlaying ? (
                  <>
                    <FaPause /> Tạm dừng
                  </>
                ) : (
                  <>
                    <FaPlay /> Phát tất cả
                  </>
                )}
              </button>
            </div>
          </div>
        </div>
      </div>

      <div className={styles.detailView}>
        <div className={styles.table}>
          <div className={styles.tableHeader}>
            <div className={styles.colIndex}>#</div>
            <div className={styles.colTitle}>Title</div>
            <div className={styles.colArtist}>Artist</div>
            <div className={styles.colDuration}>Duration</div>
            <div className={styles.colAction}></div>
          </div>

          {tracks.map((song, index) => {
            const isActive = currentTrack?.trackId === song.trackId;

            return (
              <div
                key={song.trackId}
                className={`${styles.row} ${isActive ? styles.activeRow : ""}`}
                onClick={() => handlePlaySong(index)}
              >
                <div className={styles.colIndex}>{index + 1}</div>

                <div className={styles.colTitle}>
                  <img src={song.imageUrl} alt={song.title} />
                  <span>{song.title}</span>
                </div>

                <div className={styles.colArtist}>{song.artistName}</div>
                <div className={styles.colDuration}>
                  {formatDuration(song.duration)}
                </div>
                <div className={styles.colAction}>
                  {onRemoveSong && (
                    <button
                      className={styles.removeBtn}
                      title="Xóa bài hát"
                      onClick={(e) => {
                        e.stopPropagation();
                        onRemoveSong(song.trackId);
                      }}
                    >
                      <IoTrashOutline />
                    </button>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default DetailView;

