"use client";
import { useState, useRef, useEffect } from "react";
import styles from "./UploadSongModal.module.css";
import { useModal } from "@/app/context/ModalContext";
import { useUser } from "@/app/features/user/context/UserContext";
import { uploadSongByUser } from "../song.api";
import { IoIosMusicalNote } from "react-icons/io";
import { FcPicture } from "react-icons/fc";

export default function UploadSongModal() {
  const { closeModal } = useModal();
  const { user } = useUser();

  const [title, setTitle] = useState("");
  const [artist, setArtist] = useState("");
  const [genre, setGenre] = useState("");
  const [duration, setDuration] = useState("");
  const [audioFile, setAudioFile] = useState<File | null>(null);
  const [imageFile, setImageFile] = useState<File | null>(null);

  // Khởi tạo artist mặc định là username
  useEffect(() => {
    if (user?.username) setArtist(user.username);
  }, [user]);

  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState(false);

  const audioInputRef = useRef<HTMLInputElement>(null);
  const imageInputRef = useRef<HTMLInputElement>(null);

  // Tự động lấy duration khi user chọn file audio
  const handleAudioSelect = (file: File) => {
    setAudioFile(file);

    const audio = new Audio();
    audio.src = URL.createObjectURL(file);
    audio.addEventListener("loadedmetadata", () => {
      setDuration(Math.round(audio.duration).toString());
      URL.revokeObjectURL(audio.src);
    });
  };

  const handleSubmit = async () => {
    if (submitting) return;
    setError("");

    if (!title.trim()) {
      setError("Vui lòng nhập tên bài hát.");
      return;
    }

    if (!artist.trim()) {
      setError("Vui lòng nhập tên nghệ sĩ.");
      return;
    }

    if (!audioFile) {
      setError("Vui lòng chọn file nhạc.");
      return;
    }

    try {
      setSubmitting(true);

      const formData = new FormData();
      formData.append("title", title.trim());
      formData.append("artist", artist.trim());
      formData.append("genre", genre.trim());
      formData.append("duration", duration || "0");
      formData.append("audioFile", audioFile);
      if (imageFile) formData.append("imageFile", imageFile);

      await uploadSongByUser(formData);

      setSuccess(true);
    } catch (err: any) {
      setError(err.message || "Đã xảy ra lỗi khi đăng bài hát.");
    } finally {
      setSubmitting(false);
    }
  };

  // Màn hình thành công
  if (success) {
    return (
      <div className={styles.uploadModal}>
        <div className={styles.successState}>
          <div className={styles.successIcon}>✓</div>
          <h3>Gửi bài hát thành công!</h3>
          <p>
            Bài hát <strong>"{title}"</strong> đã được gửi đến quản trị viên.
            <br />
            Bài hát sẽ được hiển thị sau khi quản trị viên duyệt.
          </p>
          <button className={styles.uploadBtn} onClick={closeModal}>
            Đóng
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className={styles.uploadModal}>
      {/* Progress overlay */}
      {submitting && (
        <div className={styles.progressOverlay}>
          <div className={styles.spinner}></div>
          <p>Đang tải lên...</p>
        </div>
      )}

      {/* Header */}
      <div className={styles.modalHeader}>
        <div className={styles.uploadIcon}><IoIosMusicalNote /></div>
        <div className={styles.headerText}>
          <h3>Đăng bài hát</h3>
          <p>Chia sẻ âm nhạc của bạn với cộng đồng</p>
        </div>
      </div>

      {/* Title */}
      <div className={styles.formGroup}>
        <label>
          Tên bài hát <span className={styles.required}>*</span>
        </label>
        <input
          type="text"
          placeholder="Nhập tên bài hát..."
          value={title}
          onChange={(e) => setTitle(e.target.value)}
        />
      </div>

      {/* Genre */}
      <div className={styles.formGroup}>
        <label>Thể loại</label>
        <input
          type="text"
          placeholder="VD: Pop, Ballad, R&B..."
          value={genre}
          onChange={(e) => setGenre(e.target.value)}
        />
      </div>

      {/* Artist */}
      <div className={styles.formGroup}>
        <label>
          Nghệ sĩ <span className={styles.required}>*</span>
        </label>
        <input
          type="text"
          placeholder="Tên nghệ sĩ..."
          value={artist}
          onChange={(e) => setArtist(e.target.value)}
        />
      </div>

      {/* Audio file + Duration row */}
      <div className={styles.formRow}>
        <div className={styles.formGroup}>
          <label>
            File nhạc <span className={styles.required}>*</span>
          </label>
          <div
            className={`${styles.fileUploadArea} ${audioFile ? styles.hasFile : ""}`}
            onClick={() => audioInputRef.current?.click()}
          >
            <input
              ref={audioInputRef}
              type="file"
              accept="audio/*"
              onChange={(e) => {
                const f = e.target.files?.[0];
                if (f) handleAudioSelect(f);
              }}
            />
            {audioFile ? (
              <span className={styles.fileName}>{audioFile.name}</span>
            ) : (
              <>
                <span className={styles.fileUploadIcon}>🎧</span>
                <span className={styles.fileUploadLabel}>
                  <strong>Chọn file</strong> hoặc kéo thả
                </span>
              </>
            )}
          </div>
        </div>

        <div className={styles.formGroup}>
          <label>Thời lượng (giây)</label>
          <input
            type="number"
            placeholder="Tự động"
            value={duration}
            onChange={(e) => setDuration(e.target.value)}
            min="0"
          />
        </div>
      </div>

      {/* Image file */}
      <div className={styles.formGroup}>
        <label>Ảnh bìa</label>
        <div
          className={`${styles.fileUploadArea} ${imageFile ? styles.hasFile : ""}`}
          onClick={() => imageInputRef.current?.click()}
        >
          <input
            ref={imageInputRef}
            type="file"
            accept="image/*"
            onChange={(e) => {
              const f = e.target.files?.[0];
              if (f) setImageFile(f);
            }}
          />
          {imageFile ? (
            <span className={styles.fileName}><FcPicture /> {imageFile.name}</span>
          ) : (
            <>
              <span className={styles.fileUploadIcon}><FcPicture /></span>
              <span className={styles.fileUploadLabel}>
                <strong>Chọn ảnh bìa</strong> (tùy chọn)
              </span>
            </>
          )}
        </div>
      </div>

      {/* Error message */}
      {error && <div className={styles.errorMsg}>{error}</div>}

      {/* Actions */}
      <div className={styles.modalActions}>
        <button
          className={styles.uploadBtn}
          onClick={handleSubmit}
          disabled={submitting}
        >
          {submitting ? "Đang tải lên..." : "Đăng bài hát"}
        </button>
        <button className={styles.cancelBtn} onClick={closeModal}>
          Hủy
        </button>
      </div>
    </div>
  );
}

import { readApiResponse } from "../../lib/api-contract";
import { Track } from "../../types/music";
import { adminFetch, userFetch } from "../../utils/refreshToken";
import { mapSongToTrack } from "@/app/utils/song.mapper";

export const URL =
  "/api";

type PaginatedSongs = {
  page: number;
  limit: number;
  total: number;
  songs: Track[];
};

export async function fetchDailySongs(
  limit = 20,
  page = 1,
): Promise<PaginatedSongs> {
  const res = await fetch(`${URL}/songs?page=${page}&limit=${limit}`);

  if (!res.ok) {
    throw new Error("Failed to fetch songs");
  }

  const data = await readApiResponse(res);

  return {
    page: data.page,
    limit: data.limit,
    total: data.total,
    songs: data.songs.map(mapSongToTrack),
  };
}

// lấy tất cả bài hát có phân trang cho trang quản trị
export async function fetchSongsForManage({
  page = 1,
  limit = 10,
  search = "",
}) {
  const params = new URLSearchParams({
    page: page.toString(),
    limit: limit.toString(),
    search,
  });

  const res = await adminFetch(`${URL}/songs/all?${params}`, {
    method: "GET",
    credentials: "include",
  });

  return readApiResponse(res);
}

export async function updateSong(id: number, data: any) {
  const res = await adminFetch(`${URL}/songs/${id}`, {
    method: "PUT",
    headers: {
      "Content-Type": "application/json",
    },
    credentials: "include",
    body: JSON.stringify(data),
  });

  if (!res.ok) throw new Error("Update failed");

  return readApiResponse(res);
}

export async function deleteSong(songId: number) {
  const res = await adminFetch(`${URL}/songs/${songId}`, {
    method: "DELETE",
    credentials: "include",
  });

  const json = await readApiResponse(res);

  if (!res.ok) {
    throw new Error(json.message || "Delete song failed");
  }

  return json;
}

// like/unlike song
export async function likeSong(songId: number) {
  const res = await userFetch(`${URL}/songs/${songId}/like`, {
    method: "POST",
    credentials: "include",
  });

  if (!res.ok) throw new Error("Like failed");
  return readApiResponse(res);
}

export async function unlikeSong(songId: number) {
  const res = await userFetch(`${URL}/songs/${songId}/like`, {
    method: "DELETE",
    credentials: "include",
  });

  if (!res.ok) throw new Error("Unlike failed");
  return readApiResponse(res);
}

export async function getLikeStatus(songId: number) {
  const res = await userFetch(`${URL}/songs/${songId}/like-status`, {
    credentials: "include",
  });

  if (!res.ok) throw new Error("Fetch like status failed");
  return readApiResponse(res);
}

export async function fetchLikedSongs() {
  const res = await userFetch(`${URL}/songs/me/favorites`, {
    method: "GET",
    credentials: "include",
  });

  const json = await readApiResponse(res);

  if (!res.ok) {
    throw new Error(json.message || "Fetch liked songs failed");
  }

  return json.data;
}

// ẩn hiện bài hát
export async function toggleSongVisibility(songId: number) {
  const res = await adminFetch(`${URL}/songs/${songId}/toggle-invisibility`, {
    method: "PATCH",
    credentials: "include",
  });

  const json = await readApiResponse(res);

  if (!res.ok) {
    throw new Error(json.message || "Toggle visibility failed");
  }

  return json;
}

// tăng view
export async function increaseSongView(songId: number) {
  await userFetch(`${URL}/songs/${songId}/view`, {
    method: "POST",
    credentials: "include",
  });
}

// tìm kiếm
export async function searchSongs(
  keyword: string,
  limit = 10,
): Promise<Track[]> {
  const res = await fetch(
    `${URL}/songs/search?q=${encodeURIComponent(keyword)}&limit=${limit}`,
    {
      credentials: "include",
    },
  );

  if (!res.ok) {
    throw new Error("Search failed");
  }

  const json = await readApiResponse(res);

  if (!json.data || !Array.isArray(json.data)) {
    return [];
  }

  return json.data.map(
    (song: any): Track => ({
      trackId: song.song_id,
      title: song.title,
      duration: song.duration || 0,
      imageUrl: song.image_url,
      artistName:
        song.artists?.length > 0
          ? song.artists.map((a: any) => a.name).join(", ")
          : "Unknown",
      audioUrl: song.audio_url,
      genre: song.genre ?? "Other",
      viewCount: 0,
      isVisible:
        song.isVisible !== undefined
          ? song.isVisible
          : song.is_visible !== undefined
            ? song.is_visible
            : true,
    }),
  );
}

export async function createSong(formData: FormData) {
  const res = await adminFetch(`${URL}/songs`, {
    method: "POST",
    credentials: "include",
    body: formData, //
  });

  if (!res.ok) {
    const err = await readApiResponse(res);
    throw new Error(err.message || "Create song failed");
  }

  return readApiResponse(res);
}

export async function uploadSongByUser(formData: FormData) {
  const res = await userFetch(`${URL}/songs/upload`, {
    method: "POST",
    credentials: "include",
    body: formData,
  });

  const json = await readApiResponse(res);

  if (!res.ok) {
    throw new Error(json.message || "Upload bài hát thất bại");
  }

  return json;
}

/* --- DUYỆT BÀI HÁT (ADMIN) --- */

export async function fetchPendingSongs({
  page = 1,
  limit = 20,
} = {}) {
  const params = new URLSearchParams({
    page: page.toString(),
    limit: limit.toString(),
  });

  const res = await adminFetch(`${URL}/songs/pending?${params}`, {
    method: "GET",
    credentials: "include",
  });

  if (!res.ok) throw new Error("Fetch pending songs failed");
  return readApiResponse(res);
}

export async function fetchPendingSongsCount() {
  const res = await adminFetch(`${URL}/songs/pending/count`, {
    method: "GET",
    credentials: "include",
  });

  if (!res.ok) return 0;
  const json = await readApiResponse(res);
  return json.count || 0;
}

export async function approveSongApi(songId: number) {
  const res = await adminFetch(`${URL}/songs/${songId}/approve`, {
    method: "PATCH",
    credentials: "include",
  });

  const json = await readApiResponse(res);
  if (!res.ok) throw new Error(json.message || "Duyệt bài hát thất bại");
  return json;
}

export async function rejectSongApi(songId: number) {
  const res = await adminFetch(`${URL}/songs/${songId}/reject`, {
    method: "PATCH",
    credentials: "include",
  });

  const json = await readApiResponse(res);
  if (!res.ok) throw new Error(json.message || "Từ chối bài hát thất bại");
